class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def reverse(head):
    """Reverse the list starting at head in place; return the new head."""
    return head

exercises.reference:
class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def reverse(head):
    prev = None
    while head is not None:
        head.next, prev, head = prev, head, head.next
    return prev
